inline bool VerifyBTParamValue(::flatbuffers::Verifier &verifier, const void *obj, BTParamValue type) {
  switch (type) {
    case BTParamValue::NONE: {
      return true;
    }
    case BTParamValue::Float: {
      return verifier.VerifyField<SE::FlatBuffers::Float>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    case BTParamValue::Bool: {
      return verifier.VerifyField<SE::FlatBuffers::Bool>(static_cast<const uint8_t *>(obj), 0, 1);
    }
    case BTParamValue::Int: {
      return verifier.VerifyField<SE::FlatBuffers::Int>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    case BTParamValue::Vec3: {
      return verifier.VerifyField<SE::FlatBuffers::Vec3>(static_cast<const uint8_t *>(obj), 0, 4);
    }
    case BTParamValue::BTParamString: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::BTParamString *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyBTParamValueVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<BTParamValue> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyBTParamValue(
        verifier,  values->Get(i), types->GetEnum<BTParamValue>(i))) {
      return false;
    }
  }
  return true;
}

inline void *BTParamValueUnion::UnPack(const void *obj, BTParamValue type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case BTParamValue::Float: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Float *>(obj);
      return new SE::FlatBuffers::Float(*ptr);
    }
    case BTParamValue::Bool: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Bool *>(obj);
      return new SE::FlatBuffers::Bool(*ptr);
    }
    case BTParamValue::Int: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Int *>(obj);
      return new SE::FlatBuffers::Int(*ptr);
    }
    case BTParamValue::Vec3: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Vec3 *>(obj);
      return new SE::FlatBuffers::Vec3(*ptr);
    }
    case BTParamValue::BTParamString: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::BTParamString *>(obj);
      return ptr->UnPack(resolver);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> BTParamValueUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case BTParamValue::Float: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Float *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BTParamValue::Bool: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Bool *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BTParamValue::Int: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Int *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BTParamValue::Vec3: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::Vec3 *>(value);
      return _fbb.CreateStruct(*ptr).Union();
    }
    case BTParamValue::BTParamString: {
      auto ptr = reinterpret_cast<const SE::FlatBuffers::BTParamStringT *>(value);
      return CreateBTParamString(_fbb, ptr, _rehasher).Union();
    }
    default: return 0;
  }
}

